<script setup lang="ts">import{onMounted,ref}from'vue';import{api}from'../infrastructure/api';const data=ref<any>({products:0,lowStock:0,purchases:0,salesToday:0,attention:[]}),loading=ref(true);onMounted(async()=>{try{data.value=(await api.get('/dashboard')).data}finally{loading.value=false}});const money=(v:number)=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(v);</script>
<template><div class="page"><div class="mb-8"><p class="eyebrow">OVERVIEW</p><h1>Good inventory starts here</h1><p class="subtitle">See what needs attention and keep operations moving.</p></div><div class="cards"><article><span>Products</span><strong>{{data.products}}</strong><small>Active catalog items</small></article><article><span>Low Stock</span><strong>{{data.lowStock}}</strong><small>Need replenishment</small></article><article><span>Purchases</span><strong>{{data.purchases}}</strong><small>Awaiting action</small></article><article><span>Sales Today</span><strong class="text-2xl">{{money(data.salesToday)}}</strong><small>Completed today</small></article></div><section class="panel mt-8"><div class="panel-head"><div><h2>Stock needs attention</h2><p>Items at or below their reorder level.</p></div><router-link to="/products" class="secondary">View all products</router-link></div><div v-if="loading" class="empty">Loading dashboard…</div><div v-else-if="!data.attention.length" class="empty">Everything looks healthy. No low-stock items.</div><div v-else class="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Available</th><th>Status</th></tr></thead><tbody><tr v-for="p in data.attention" :key="p.id"><td><strong>{{p.name}}</strong><small>{{p.sku}}</small></td><td>{{p.category}}</td><td>{{p.stockOnHand}} {{p.unit}}</td><td><span class="badge danger">Low Stock</span></td></tr></tbody></table></div></section></div></template>
